#!/usr/bin/env python3
# -----------------------------------------------------------------------------
# Mock GripperCommand action server (no-op), generated by the TrainIt Setup Assistant.
#
# In mock mode there is no real gripper hardware/bridge, so the BT's CloseGripper /
# OpenGripper would block on a missing action server. This stand-in serves
# control_msgs/action/GripperCommand on the configured namespace and immediately
# succeeds, so the pick&place logic runs end-to-end. In isaac/real the cell's real
# gripper bridge serves this action instead (this node is launched only in mock).
# -----------------------------------------------------------------------------
import rclpy
from rclpy.action import ActionServer
from rclpy.node import Node

from control_msgs.action import GripperCommand


class MockGripperActionServer(Node):
    def __init__(self):
        super().__init__('mock_gripper_action_server')
        self._action = self.declare_parameter(
            'action', '/gripper_position_controller/gripper_cmd').get_parameter_value().string_value
        self._server = ActionServer(self, GripperCommand, self._action, self._execute)
        self.get_logger().info(f'mock gripper action server ready on {self._action}')

    def _execute(self, goal_handle):
        cmd = goal_handle.request.command
        self.get_logger().info(
            f'mock gripper: position={cmd.position:.2f} -> succeed (no-op)')
        goal_handle.succeed()
        result = GripperCommand.Result()
        result.position = cmd.position
        result.reached_goal = True
        result.stalled = False
        return result


def main():
    rclpy.init()
    node = MockGripperActionServer()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    node.destroy_node()
    if rclpy.ok():
        rclpy.shutdown()


if __name__ == '__main__':
    main()
